export function aCamel(texto) {
  return texto
    .toLowerCase()
    .replace(/[-_\s]+(.)?/g, (_, letra) => /* la letra en mayúscula, o "" si no hay */);
}

export function aSlug(texto) {
  return texto
    .normalize("NFD")
    .replace(/* las tildes sueltas */, "")
    .toLowerCase()
    .replace(/* lo que no es a-z ni 0-9 */, "-")
    .replace(/* guiones al inicio o al final */, "");
}
